<template>
	<view class="custom-navigation">
		<!-- 状态栏占位 -->
		<view class="status-bar" :style="{ height: statusBarHeight + 'px' }"></view>
		
		<!-- 导航栏内容 -->
		<view class="nav-content" :style="{ height: navBarHeight + 'px' }" v-if="!hideTitle">
			<view class="nav-left" @click="onBack" v-if="showBack">
				<text class="back-icon">‹</text>
			</view>
			<view class="nav-center">
				<text class="nav-title">{{ title }}</text>
			</view>
			<view class="nav-right" @click="onRightClick" v-if="rightText">
				<text class="right-text">{{ rightText }}</text>
			</view>
		</view>
		
		<!-- 搜索栏区域 - 只在首页显示 -->
		<view class="search-section" v-if="showSearch">
			<view class="city-section">
				<text class="city-name">{{ cityName }}</text>
				<text class="arrow">></text>
			</view>
			<view class="search-input-wrapper">
				<input 
					class="search-input" 
					type="text" 
					:placeholder="searchPlaceholder" 
					v-model="searchValue"
					@focus="onSearchFocus"
					@blur="onSearchBlur"
				/>
				<text class="search-icon">🔍</text>
			</view>
		</view>
	</view>
</template>

<script>
	export default {
		name: 'CustomNavigation',
		props: {
			title: {
				type: String,
				default: '标题'
			},
			showBack: {
				type: Boolean,
				default: true
			},
			rightText: {
				type: String,
				default: ''
			},
			backgroundColor: {
				type: String,
				default: '#1890FF'
			},
			showSearch: {
				type: Boolean,
				default: false
			},
			cityName: {
				type: String,
				default: '北京'
			},
			searchPlaceholder: {
				type: String,
				default: '搜索充电桩、地点'
			},
			hideTitle: {
				type: Boolean,
				default: false
			}
		},
		data() {
			return {
				statusBarHeight: 0,
				navBarHeight: 44,
				searchValue: ''
			}
		},
		mounted() {
			this.getSystemInfo();
		},
		methods: {
			getSystemInfo() {
				const systemInfo = uni.getSystemInfoSync();
				// 获取状态栏高度，如果没有则使用默认值
				this.statusBarHeight = systemInfo.statusBarHeight || 20;
				// 设置导航栏高度
				this.navBarHeight = 44;
			},
			onBack() {
				this.$emit('back');
				// 默认返回上一页
				uni.navigateBack({
					delta: 1
				});
			},
			onRightClick() {
				this.$emit('rightClick');
			},
			onSearchFocus() {
				this.$emit('searchFocus');
			},
			onSearchBlur() {
				this.$emit('searchBlur');
			}
		}
	}
</script>

<style scoped>
	.custom-navigation {
		position: fixed;
		top: 0;
		left: 0;
		right: 0;
		z-index: 1000;
		background-color: #1890FF;
	}
	
	.status-bar {
		width: 100%;
		background-color: #1890FF;
	}
	
	.nav-content {
		display: flex;
		align-items: center;
		justify-content: space-between;
		padding: 0 20rpx; /* 减少左右内边距，为搜索栏留出更多空间 */
		background-color: #1890FF;
	}
	
	.nav-left {
		width: 80rpx;
		height: 100%;
		display: flex;
		align-items: center;
		justify-content: flex-start;
	}
	
	.back-icon {
		font-size: 48rpx;
		color: #ffffff;
		font-weight: bold;
		line-height: 1;
	}
	
	.nav-center {
		flex: 1;
		display: flex;
		align-items: center;
		justify-content: center;
	}
	
	.nav-title {
		font-size: 36rpx;
		color: #ffffff;
		font-weight: 500;
		text-align: center;
	}
	
	.nav-right {
		width: 80rpx;
		height: 100%;
		display: flex;
		align-items: center;
		justify-content: flex-end;
	}
	
	.right-text {
		font-size: 32rpx;
		color: #ffffff;
	}
	
	/* 搜索栏样式 */
	.search-section {
		background-color: #1890FF;
		padding: 15rpx 20rpx 20rpx 20rpx; /* 减少上下内边距，减少左右内边距 */
		display: flex;
		align-items: center;
		box-shadow: 0 2rpx 10rpx rgba(0, 0, 0, 0.1);
		width: 100%; /* 确保搜索栏占满整个宽度 */
		box-sizing: border-box; /* 包含内边距在宽度内 */
	}
	
	/* 当隐藏标题时，搜索栏直接位于状态栏下方 */
	.custom-navigation:has(.search-section) .search-section {
		margin-top: 0;
	}
	
	.city-section {
		display: flex;
		align-items: center;
		margin-right: 12rpx; /* 进一步减少右边距 */
		flex-shrink: 0; /* 防止城市名被压缩 */
		white-space: nowrap; /* 防止城市名换行 */
	}
	
	.city-name {
		font-size: 30rpx; /* 稍微减小字体 */
		color: #ffffff;
		font-weight: 500;
	}
	
	.arrow {
		font-size: 22rpx; /* 稍微减小箭头 */
		color: #ffffff;
		margin-left: 6rpx; /* 减少左边距 */
		opacity: 0.8;
	}
	
	.search-input-wrapper {
		flex: 1;
		position: relative;
		background-color: #ffffff;
		border-radius: 50rpx;
		height: 70rpx;
		display: flex;
		align-items: center;
		padding: 0 12rpx; /* 进一步减少左右内边距 */
		min-width: 0; /* 允许flex项目收缩 */
		margin: 0; /* 确保没有外边距 */
	}
	
	.search-input {
		flex: 1;
		height: 100%;
		font-size: 28rpx;
		color: #333333;
		border: none;
		outline: none;
		background: transparent;
		min-width: 0; /* 允许输入框收缩 */
		width: 100%; /* 确保输入框占满容器 */
		padding: 0; /* 移除默认内边距 */
	}
	
	.search-input::placeholder {
		color: #999999;
	}
	
	.search-icon {
		font-size: 30rpx; /* 稍微减小图标 */
		color: #1890FF;
		margin-left: 8rpx; /* 减少左边距 */
		flex-shrink: 0; /* 防止图标被压缩 */
	}
</style>
